<?php session_start();require_once dirname(__DIR__).'/lib.php';if(!empty($_SESSION['admin'])){header('Location:index.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){if(hash_equals((string)cfg('admin.id'),trim($_POST['id']??''))&&password_verify($_POST['pw']??'',(string)cfg('admin.password_hash'))){$_SESSION['admin']=true;session_regenerate_id(true);header('Location:index.php');exit;}$err='아이디 또는 비밀번호가 올바르지 않습니다.';}?><!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/app.css"><title>관리자 로그인</title></head><body><main class="narrow"><h1>관리자 로그인</h1><?php if($err):?><div class="alert err"><?=e($err)?></div><?php endif?><form method="post" class="card"><label>아이디<input name="id" required></label><label>비밀번호<input type="password" name="pw" required></label><br><button class="btn big">로그인</button></form></main></body></html>